    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum funcaoUsuario {\n  Aluno\n  Monitor\n}\n\nenum modalidadePref {\n  Presencial\n  Online\n  Nenhuma\n}\n\nenum statusSolicit {\n  Pendente\n  Aceita\n}\n\nenum statusMonitor {\n  Marcada\n  Concluida\n  Cancelada\n}\n\nenum periodos {\n  Primeiro\n  Segundo\n  Terceiro\n  Quarto\n  Quinto\n  Sexto\n}\n\nmodel Usuario {\n  id            Int                  @id @default(autoincrement())\n  nome          String               @db.VarChar(100)\n  email         String               @unique @db.VarChar(100)\n  senha_hash    String               @db.VarChar(100)\n  funcao        funcaoUsuario\n  curso         String               @db.VarChar(50)\n  periodo       periodos\n  is_admin      Boolean              @default(false)\n  ativo         Boolean              @default(true)\n  criado_em     DateTime             @db.Timestamptz()\n  atualizado_em DateTime             @db.Timestamptz()\n  solicitacoes  Solicitacoes[]\n  monitoria     Monitoria[]\n  user_materia  Usuario_Disciplina[]\n}\n\nmodel Disciplinas {\n  id            Int                  @id @default(autoincrement())\n  nome          String               @db.VarChar(100)\n  codigo        String               @db.VarChar(50)\n  ativo         Boolean              @default(true)\n  criado_em     DateTime             @db.Timestamptz()\n  atualizado_em DateTime             @db.Timestamptz()\n  solicitacoes  Solicitacoes[]\n  user_materia  Usuario_Disciplina[]\n}\n\nmodel Solicitacoes {\n  id                  Int            @id @default(autoincrement())\n  aluno_id            Int\n  aluno               Usuario        @relation(fields: [aluno_id], references: [id])\n  disciplina_id       Int\n  disciplina          Disciplinas    @relation(fields: [disciplina_id], references: [id])\n  assunto             String         @db.VarChar(100)\n  descricao           String?        @db.VarChar(500)\n  preferencia_data    DateTime       @db.Date()\n  preferencia_horario DateTime       @db.Time()\n  preferencia_modal   modalidadePref\n  preferencia_local   String?        @db.VarChar(100)\n  status              statusSolicit  @default(Pendente)\n  criado_em           DateTime       @db.Timestamptz()\n  atualizado_em       DateTime       @db.Timestamptz()\n  monitoria           Monitoria[]\n}\n\nmodel Monitoria {\n  id                   Int            @id @default(autoincrement())\n  solicitacao_id       Int\n  solicitacao          Solicitacoes   @relation(fields: [solicitacao_id], references: [id])\n  monitor_id           Int\n  monitor              Usuario        @relation(fields: [monitor_id], references: [id])\n  data                 DateTime       @db.Timestamptz()\n  horario_inicio       DateTime       @db.Time()\n  horario_fim          DateTime       @db.Time()\n  modalidade           modalidadePref\n  local                String         @db.VarChar(250)\n  link                 String?\n  status               statusMonitor  @default(Marcada)\n  justificativa_cancel String?        @db.VarChar(300)\n  criado_em            DateTime       @db.Timestamptz()\n  atualizado_em        DateTime       @db.Timestamptz()\n}\n\nmodel Usuario_Disciplina {\n  id            Int           @id @default(autoincrement())\n  usuario_id    Int\n  usuario       Usuario       @relation(fields: [usuario_id], references: [id])\n  disciplina_id Int\n  disciplina    Disciplinas   @relation(fields: [disciplina_id], references: [id])\n  funcao        funcaoUsuario\n  criado_em     DateTime      @db.Timestamptz()\n\n  @@unique([usuario_id, disciplina_id])\n}\n",
